public interface IRepository<T>
{
    void Add(T item);
    int Count { get; }
    IReadOnlyList<T> All();

    // A DEFAULT member: implementors get it free, and may override it.
    bool IsEmpty => Count == 0;
}

public class MemoryRepository<T> : IRepository<T>
{
    private readonly List<T> _items = [];

    public void Add(T item) => throw new NotImplementedException();

    public int Count => throw new NotImplementedException();

    public IReadOnlyList<T> All() => throw new NotImplementedException();
}

public interface ICounter
{
    // Reset to zero.
    void Reset();
}

public interface IRewindable
{
    // Step back by one.
    void Reset();
}

// Implements BOTH Reset methods, with different meanings. Only possible
// with explicit implementation.
public class DualCounter : ICounter, IRewindable
{
    public int Value { get; private set; }

    public void Bump() => Value++;

    void ICounter.Reset() => throw new NotImplementedException();

    void IRewindable.Reset() => throw new NotImplementedException();
}

